#[derive(Clone, Copy, Debug, PartialEq)]
#[repr(u16)]
pub enum Model3Alg {
    /// For test purposes only
    None = 0,
    AesGmac64 = 1,
    Ecc256 = 2,
}

impl Model3Alg {
    pub fn from_repr(repr: u16) -> Option<Model3Alg> {
        match repr {
            0 => Some(Model3Alg::None),
            1 => Some(Model3Alg::AesGmac64),
            2 => Some(Model3Alg::Ecc256),
            _ => None,
        }
    }
}

/// Short, spec-matching alias for [`Model3Alg`] - only `Model3Alg` (unique per model) reaches the generated C header, since cbindgen has no module system to keep `Alg` distinct from another model's point of the same name.
pub type Alg = Model3Alg;
